package com.paysense.service;

import com.paysense.api.SecurityModels.*;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;
import java.util.Locale;

@Service
public class SecurityAssessmentService {
 private static final List<String> BLOCKED=List.of("collect","receive","refund","cashback","prize","lottery","kyc update","verify account","urgent");
 public AnalyzeResponse analyze(AnalyzeRequest r){int score=8;var layers=new java.util.ArrayList<LayerResult>();layers.add(new LayerResult(1,"Input validation","PASS","UPI ID and amount have valid formats."));String note=(r.note()==null?"":r.note()).toLowerCase(Locale.ROOT);boolean scam=BLOCKED.stream().anyMatch(note::contains);if(scam)score+=48;layers.add(new LayerResult(2,"Scam-language screening",scam?"WARN":"PASS",scam?"Payment note contains wording frequently used in social-engineering scams.":"No common scam phrases found."));if(r.amount().compareTo(new BigDecimal("5000"))>0)score+=25;else if(r.amount().compareTo(new BigDecimal("1000"))>0)score+=10;layers.add(new LayerResult(3,"Amount anomaly",r.amount().compareTo(new BigDecimal("5000"))>0?"WARN":"PASS",r.amount().compareTo(new BigDecimal("5000"))>0?"Large amount: verify the recipient independently.":"Amount is within the usual demo risk range."));boolean collect=r.upiId().toLowerCase(Locale.ROOT).contains("collect");if(collect)score+=35;layers.add(new LayerResult(4,"Recipient identifier",collect?"WARN":"PASS",collect?"Recipient identifier contains a high-risk collect marker.":"UPI ID format is valid; ownership is not verified by this demo."));layers.add(new LayerResult(5,"Behavioral model","UNAVAILABLE","No trained fraud model is configured; this assessment uses transparent rules only."));layers.add(new LayerResult(6,"Community intelligence","UNAVAILABLE","Community report matching is not configured for this recipient."));layers.add(new LayerResult(7,"Guardian policy","PASS","Guardian approvals are not configured for this account."));score=Math.min(score,100);String level=score>=70?"HIGH":score>=35?"MEDIUM":"LOW";return new AnalyzeResponse(score,level,score>=35,score>=70?"Stop and independently verify this payment before continuing.":score>=35?"Pause and verify the recipient using a trusted channel.":"No strong risk indicators were found; always verify the recipient.",List.of("Never share your UPI PIN or OTP.","You do not enter a PIN to receive money.","Verify the UPI ID and name before approving."),List.copyOf(layers));}
 @Cacheable(value="security-layers",key="'v1'") public List<String> layers(){return List.of("Input validation","Scam-language screening","Amount anomaly","Recipient identifier","Behavioral model (not configured)","Community intelligence (not configured)","Guardian policy (not configured)");}
 public ScamEducation education(String type){return switch(type.toLowerCase(Locale.ROOT)){case "collect-request"->new ScamEducation(type,"Fake collect request","A scammer asks you to approve a request and enter your UPI PIN. Approving a collect request sends money.",List.of("Unexpected collect request","Pressure to approve quickly","Request claims money will be received"),List.of("Decline the request","Never enter your PIN to receive money","Report the UPI ID to your payment provider"));case "qr-code"->new ScamEducation(type,"QR code payment scam","Scanning a QR code and entering your UPI PIN authorizes a payment; it does not receive money.",List.of("Stranger sends a QR to receive funds","Request to enter PIN after scanning","QR shared under urgent pressure"),List.of("Do not scan unknown payment QR codes","Check recipient name and amount","Cancel if the details differ"));default->new ScamEducation(type,"UPI safety basics","Treat unexpected payment requests, calls, and links with caution.",List.of("Urgency or threats","Requests for PIN, OTP, or screen sharing","Promises of prizes or refunds"),List.of("Never disclose your UPI PIN or OTP","Verify using an official number","Report suspected fraud promptly"));};}
}
